package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var curRec LedgerRec
var scanner *bufio.Scanner
var ledgerFile *os.File

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeSigned(v decimal.Decimal, nInt int) decimal.Decimal {
	t := v.Truncate(2)
	sc := t.Shift(2).IntPart()
	m := pow10(nInt + 2)
	sc = sc % m
	return decimal.New(sc, -2)
}

func formatEdited(absScaled int64, intPat string, nInt int) string {
	frac := absScaled % 100
	intPart := (absScaled / 100) % pow10(nInt)
	digits := make([]byte, nInt)
	tmp := intPart
	for i := nInt - 1; i >= 0; i-- {
		digits[i] = byte('0' + tmp%10)
		tmp /= 10
	}
	var b strings.Builder
	suppressing := true
	di := 0
	for i := 0; i < len(intPat); i++ {
		ch := intPat[i]
		if ch == ',' {
			if suppressing {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		} else if ch == 'Z' {
			d := digits[di]
			di++
			if suppressing && d == '0' {
				b.WriteByte(' ')
			} else {
				b.WriteByte(d)
				suppressing = false
			}
		} else if ch == '9' {
			d := digits[di]
			di++
			b.WriteByte(d)
			suppressing = false
		}
	}
	b.WriteByte('.')
	b.WriteByte(byte('0' + frac/10))
	b.WriteByte(byte('0' + frac%10))
	return b.String()
}

func scaledAbs(v decimal.Decimal) int64 {
	t := v.Truncate(2)
	sc := t.Shift(2).IntPart()
	if sc < 0 {
		sc = -sc
	}
	return sc
}

func moveAmtEd(v decimal.Decimal) string {
	sc := scaledAbs(v)
	return formatEdited(sc, "ZZ,ZZ9", 5)
}

func moveBalEd(v decimal.Decimal) string {
	neg := v.Sign() < 0
	sc := scaledAbs(v)
	s := " "
	if neg {
		s = "-"
	}
	return s + formatEdited(sc, "Z,ZZZ,ZZ9", 7)
}

func moveTotEd(v decimal.Decimal) string {
	neg := v.Sign() < 0
	sc := scaledAbs(v)
	s := " "
	if neg {
		s = "-"
	}
	return s + formatEdited(sc, "ZZZ,ZZZ,ZZ9", 9)
}

func displaySkipped(v int64) string {
	m := ((v % 100) + 100) % 100
	return fmt.Sprintf("%02d", m)
}

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
		// truncate or pad to 14
		if len(line) > 14 {
			line = line[:14]
		} else if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		}
		curRec.BrBranch = line[0:2]
		curRec.BrAcct = line[2:6]
		curRec.BrType = line[6:7]
		amtStr := line[7:14]
		var n int64 = 0
		for i := 0; i < len(amtStr); i++ {
			c := amtStr[i]
			var d int64 = 0
			if c >= '0' && c <= '9' {
				d = int64(c - '0')
			} else {
				d = 0
			}
			n = n*10 + d
		}
		curRec.BrAmt = decimal.New(n, -2)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = moveAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeSigned(WsBal.Add(curRec.BrAmt), 7)
		out := curRec.BrAcct + " D " + WsAmtEd
		fmt.Fprint(os.Stdout, out+"\n")
	case "C":
		WsBal = storeSigned(WsBal.Sub(curRec.BrAmt), 7)
		out := curRec.BrAcct + " C " + WsAmtEd
		fmt.Fprint(os.Stdout, out+"\n")
	default:
		WsSkipped = (WsSkipped + 1) % 100
		out := curRec.BrAcct + " ? SKIPPED"
		fmt.Fprint(os.Stdout, out+"\n")
	}
}

func AcctBreakPara() {
	WsBalEd = moveBalEd(WsBal)
	out := "  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd
	fmt.Fprint(os.Stdout, out+"\n")
	WsBranchTot = storeSigned(WsBranchTot.Add(WsBal), 9)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = moveTotEd(WsBranchTot)
	out := " BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd
	fmt.Fprint(os.Stdout, out+"\n")
	WsGrandTot = storeSigned(WsGrandTot.Add(WsBranchTot), 9)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = moveTotEd(WsGrandTot)
	out := "GRAND TOTAL:" + WsTotEd
	fmt.Fprint(os.Stdout, out+"\n")
	out2 := "SKIPPED: " + displaySkipped(WsSkipped)
	fmt.Fprint(os.Stdout, out2+"\n")
}

func main() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			// treat missing as empty
			WsFirstFlag = "Y"
			WsEofFlag = "Y"
			// still need grand para with no breaks
			GrandPara()
			return
		}
		fmt.Fprint(os.Stderr, err.Error()+"\n")
		os.Exit(1)
	}
	defer ledgerFile.Close()
	scanner = bufio.NewScanner(ledgerFile)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	// do not strip spaces; scanner keeps them
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	ledgerFile.Close()
	GrandPara()
	if err := scanner.Err(); err != nil {
		fmt.Fprint(os.Stderr, err.Error()+"\n")
		os.Exit(1)
	}
}
